# The shipped assertions and JSON goldens are Claude-host goldens. Pin the
# suite before any test body runs; detection occurs at call time, and tests that
# need another host override locally. This pin deliberately leaks into every
# _clean_env child and clobbers any dev-shell value by design.
os.environ["CREW_HOST"] = "claude"


def log_pass(name: str) -> None:
    global PASS_COUNT
    print(f"{GREEN}✓ PASS{NC}: {name}")
    PASS_COUNT += 1


def log_fail(name: str, expected: str, got: str) -> None:
    global FAIL_COUNT
    print(f"{RED}✗ FAIL{NC}: {name}")
    print(f"  Expected: {expected}")
    print(f"  Got: {got}")
    FAIL_COUNT += 1


def log_section(name: str) -> None:
    print()
    print(f"{YELLOW}=== {name} ==={NC}")


def check(name: str, cond: bool, expected: str = "", got: str = "") -> None:
    if cond:
        log_pass(name)
    else:
        log_fail(name, expected or "True", got or "False")


# =============================================================================
# Fake executable helpers — write a tiny script onto a temp PATH dir.
# =============================================================================

def make_fake_bin(dir_path: Path, name: str, script_body: str) -> Path:
    p = dir_path / name
    p.write_text("#!/usr/bin/env python3\n" + textwrap.dedent(script_body))
    p.chmod(0o755)
    return p


# One empty dir shared by every subprocess env this suite builds: HOME is ALWAYS
# neutralized to it so a developer's real ~/.crew-config.toml can never leak into
# a subprocess test. Without this, a real global config (e.g. [dispatch].seat =
# "cursor-gpt") reroutes dispatch/panel resolution to a REAL, BILLABLE CLI instead
# of the fake bins on PATH. Tests that need a populated HOME override env["HOME"]
# after calling path_with().
_NEUTRAL_HOME = tempfile.mkdtemp(prefix="crew-test-neutral-home-")


def _neutral_env() -> dict:
    env = dict(os.environ)
    env["HOME"] = _NEUTRAL_HOME
    # Drop CLAUDE_PROJECT_DIR so the shared crew_base() resolver falls back to the
    # subprocess cwd, except a terminal `.crew` fallback cwd re-anchors to its
    # parent with a one-time stderr advisory. An ambient value from the surrounding
    # session/CI would otherwise anchor `.crew` OUTSIDE the temp tree, so every e2e
    # path assertion below is denominated against cwd, not the ambient.
    env.pop("CLAUDE_PROJECT_DIR", None)
    return env


def path_with(*dirs: Path) -> dict:
    env = _neutral_env()
    env["PATH"] = os.pathsep.join(str(d) for d in dirs) + os.pathsep + env.get("PATH", "")
    return env


# =============================================================================
# Config helpers — point the layered loaders (per-repo + global) at temp files.
# =============================================================================

from contextlib import contextmanager  # noqa: E402


@contextmanager
def crew_config(*, project=None, glob=None):
    """Point the per-repo (``CLAUDE_PROJECT_DIR``/.crew/config.toml) AND global
    (``$HOME``/~/.crew-config.toml) loaders at FRESH temp dirs, reset the memoized
    config on enter/exit, and yield the project ``Path``.

    Either layer omitted = that file ABSENT (so the layer is empty, NOT the real
    machine's file — ``$HOME`` is always neutralized to a temp dir so a developer's
    real ~/.crew-config.toml can never leak into a test). ``Path.home()`` honors
    ``$HOME`` on POSIX, so the global loader resolves into the temp home.
    """
    from multiagent import config
    saved = {k: os.environ.get(k) for k in ("CLAUDE_PROJECT_DIR", "HOME")}
    with tempfile.TemporaryDirectory() as proj, tempfile.TemporaryDirectory() as home:
        if project is not None:
            crew = Path(proj) / ".crew"
            crew.mkdir(parents=True)
            (crew / "config.toml").write_text(project)
        if glob is not None:
            (Path(home) / ".crew-config.toml").write_text(glob)
        os.environ["CLAUDE_PROJECT_DIR"] = proj
        os.environ["HOME"] = home
        config._reset_cache_for_tests()
        try:
            yield Path(proj)
        finally:
            for k, v in saved.items():
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
            config._reset_cache_for_tests()


def project_config(toml_text, *, write_file=True):
    """Per-repo config ctxmgr (global layer neutralized). ``write_file=False`` =
    no per-repo file (missing-file posture)."""
    return crew_config(project=toml_text if write_file else None)


def shipped_seats(provider):
    """The SHIPPED catalog rows for one provider, in catalog order — the roster as
    seats.toml declares it, with no config layer folded in. Config-independent, so
    an assertion about the built-in roster stays true on a machine that declares
    seats of its own."""
    from multiagent import seats as _seats
    return {n: s for n, s in _seats.shipped_catalog().items() if s.provider == provider}


def global_home(toml_text, *, write_file=True):
    """Global ~/.crew-config.toml ctxmgr (no per-repo file). ``write_file=False`` =
    no global file."""
    return crew_config(glob=toml_text if write_file else None)


# =============================================================================
# CodexProvider tests (mocked subprocess via a fake `codex` on PATH)
# =============================================================================

def test_codex():
    log_section("CodexProvider")
    prov = CodexProvider()

    # is_available outcomes
    with tempfile.TemporaryDirectory() as td:
        d = Path(td)
        # absent
        old_path = os.environ["PATH"]
        os.environ["PATH"] = str(d)
        try:
            avail, diag = prov.is_available()
            check("codex is_available absent -> (False, diag)",
                  avail is False and bool(diag), "(False, non-empty)", f"({avail}, {diag!r})")
            # present
            make_fake_bin(d, "codex", "import sys\n")
            avail, diag = prov.is_available()
            check("codex is_available present -> (True, '')",
                  avail is True and diag == "", "(True, '')", f"({avail}, {diag!r})")
        finally:
            os.environ["PATH"] = old_path

    # run() success: capture argv, stdin, write -o file
    with tempfile.TemporaryDirectory() as td:
        d = Path(td)
        capture = d / "capture.json"
        body = f"""
        import sys, json
        args = sys.argv[1:]
        stdin = sys.stdin.read()
        # find -o file
        out = None
        for i, a in enumerate(args):
            if a == "-o":
                out = args[i + 1]
        with open({str(capture)!r}, "w") as f:
            json.dump({{"args": args, "stdin": stdin}}, f)
        with open(out, "w") as f:
            f.write("CODEX REVIEW OK")
        sys.exit(0)
        """
        make_fake_bin(d, "codex", body)
        env_path = os.environ["PATH"]
        os.environ["PATH"] = str(d) + os.pathsep + env_path
        try:
            res = prov.run("PROMPT-BODY", model="o3", timeout=30)
        finally:
            os.environ["PATH"] = env_path

        cap = json.loads(capture.read_text())
        check("codex argv: exec -, --ignore-user-config, -c reasoning=xhigh, --sandbox, --skip-git-repo-check, -o",
              cap["args"][0] == "exec" and cap["args"][1] == "-"
              and "--ignore-user-config" in cap["args"]
              and "-c" in cap["args"] and "model_reasoning_effort=xhigh" in cap["args"]
              and "--sandbox" in cap["args"] and "--skip-git-repo-check" in cap["args"]
              and "-o" in cap["args"],
              "exec - --ignore-user-config -c model_reasoning_effort=xhigh --sandbox ... -o", str(cap["args"]))
        check("codex argv carries NO prompt body (stdin only)",
              "PROMPT-BODY" not in cap["args"], "no prompt in argv", str(cap["args"]))
        check("codex prompt delivered via stdin", cap["stdin"] == "PROMPT-BODY",
              "PROMPT-BODY", cap["stdin"])
        check("codex --model passed through", "--model" in cap["args"] and "o3" in cap["args"],
              "--model o3", str(cap["args"]))
        check("codex reads output from -o file -> ok",
              res.ok and res.output == "CODEX REVIEW OK", "ok=True 'CODEX REVIEW OK'",
              f"ok={res.ok} {res.output!r}")

    # run() nonzero exit -> error populated
    with tempfile.TemporaryDirectory() as td:
        d = Path(td)
        make_fake_bin(d, "codex", """
        import sys
        sys.stderr.write("not authenticated")
        sys.exit(1)
        """)
        env_path = os.environ["PATH"]
        os.environ["PATH"] = str(d) + os.pathsep + env_path
        try:
            res = prov.run("p", timeout=30)
        finally:
            os.environ["PATH"] = env_path
        check("codex nonzero exit -> ok=False with error (auth-fail path)",
              res.ok is False and res.error and "not authenticated" in res.error,
              "ok=False, error contains stderr", f"ok={res.ok} error={res.error!r}")

    # run() timeout -> ok=False
    with tempfile.TemporaryDirectory() as td:
        d = Path(td)
        make_fake_bin(d, "codex", """
        import time
        time.sleep(10)
        """)
        env_path = os.environ["PATH"]
        os.environ["PATH"] = str(d) + os.pathsep + env_path
        try:
            res = prov.run("p", timeout=1)
        finally:
            os.environ["PATH"] = env_path
        check("codex timeout -> ok=False with timeout error",
              res.ok is False and res.error and "timed out" in res.error,
              "ok=False timed out", f"ok={res.ok} error={res.error!r}")


# =============================================================================
# ClaudeProvider tests (direct construction; host-resolution coverage is separate)
# =============================================================================

def test_claude():
    log_section("ClaudeProvider")
    from multiagent import channels, providers
    from multiagent.providers import claude as claude_module
    from multiagent.providers._proc import TIMEOUT

    ClaudeProvider = claude_module.ClaudeProvider
    provider = ClaudeProvider("opus", default_model="opus")
    registry_classes = providers._provider_classes()
    check("claude-code provider kind is registered",
          registry_classes.get("claude-code", (None,))[0] is ClaudeProvider,
          "claude-code -> ClaudeProvider", repr(registry_classes))
    check("ClaudeProvider is explicitly read-only and non-continuable",
          provider.supports_workspace_write is False
          and provider.supports_continuation is False
          and provider.DISPATCH_OPTIONS == {},
          "False / False / {}",
          f"{provider.supports_workspace_write} / "
          f"{provider.supports_continuation} / {provider.DISPATCH_OPTIONS}")

    original_run_reaped = claude_module.run_reaped
    calls: list[dict] = []

    def fake_run_reaped(argv, **kwargs):
        calls.append({"argv": argv, **kwargs})
        return 0, "\x1b[32mCLAUDE REVIEW OK\x1b[0m\n", ""

    claude_module.run_reaped = fake_run_reaped
    try:
        result = provider.run("PROMPT-BODY", timeout=17)
    finally:
        claude_module.run_reaped = original_run_reaped

    expected_tools = (
        "Read,Grep,Glob,Bash(git diff:*),Bash(git --no-pager diff:*),"
        "Bash(git show:*),Bash(git log:*),Bash(git status:*),Bash(git ls-files:*)"
    )
    expected_argv = [
        "claude", "-p", "--permission-mode", "plan", "--allowedTools",
        expected_tools, "--model", "opus",
    ]
    captured = calls[0] if calls else {}
    check("claude argv is the pinned read-only form",
          captured.get("argv") == expected_argv
          and "--output-format" not in captured.get("argv", []),
          repr(expected_argv), repr(captured.get("argv")))
    from state_discovery import crew_base
    check("claude prompt is delivered by stdin and cwd is crew_base",
          captured.get("input_text") == "PROMPT-BODY"
          and captured.get("cwd") == str(crew_base())
          and captured.get("env") is not None,
          "stdin prompt, crew cwd, explicit child env", repr(captured))
    check("claude success strips ANSI and leaves channel unset",
          result.ok is True and result.output == "CLAUDE REVIEW OK"
          and result.model == "opus" and result.channel is None,
          "ok, clean output, model opus, channel None", repr(result))

    calls.clear()

    def fake_no_model(argv, **kwargs):
        calls.append({"argv": argv, **kwargs})
        return 0, "", ""

    claude_module.run_reaped = fake_no_model
    try:
        no_model = ClaudeProvider("claude").run("P")
        no_model_call = calls[0] if calls else {}
    finally:
        claude_module.run_reaped = original_run_reaped
    check("claude omits --model when no model is pinned",
          "--model" not in no_model_call.get("argv", [])
          and no_model.error == "claude returned no output",
          "no --model and no-output diagnostic", repr(no_model))

    def run_with_response(response):
        claude_module.run_reaped = lambda argv, **kwargs: response
        try:
            return provider.run("P", timeout=23)
        finally:
            claude_module.run_reaped = original_run_reaped

    timed_out = run_with_response(TIMEOUT)
    check("claude timeout maps to the pinned diagnostic",
          timed_out.ok is False and timed_out.error == "claude timed out after 23s",
          "claude timed out after 23s", repr(timed_out))
    nonzero = run_with_response((3, "ignored", "permission denied\n"))
    check("claude nonzero exit uses stripped stderr",
          nonzero.ok is False and nonzero.error == "permission denied",
          "permission denied", repr(nonzero))
    status = run_with_response((7, "", ""))
    check("claude nonzero exit without stderr uses status",
          status.ok is False and status.error == "claude exited with status 7",
          "claude exited with status 7", repr(status))
    launch_error = None

    def raise_launch(argv, **kwargs):
        raise OSError("binary disappeared")

    claude_module.run_reaped = raise_launch
    try:
        launch_error = provider.run("P")
    finally:
        claude_module.run_reaped = original_run_reaped
    check("claude launch OSError is a failed seat, not a traceback",
          launch_error is not None
          and launch_error.ok is False
          and launch_error.error == "claude launch failed: binary disappeared",
          "claude launch failed: binary disappeared", repr(launch_error))

    saved_scrubbed = {name: os.environ.get(name) for name in claude_module._SCRUBBED_ENV_NAMES}
    saved_sentinel = os.environ.get("CREW_TEST_SENTINEL")
    saved_plugin_root = os.environ.get("CLAUDE_PLUGIN_ROOT")
    for name in claude_module._SCRUBBED_ENV_NAMES:
        os.environ[name] = "outer-marker"
    os.environ["CREW_TEST_SENTINEL"] = "kept"
    os.environ["CLAUDE_PLUGIN_ROOT"] = "/plugin/root"
    env_capture: dict = {}

    def capture_env(argv, **kwargs):
        env_capture.update(kwargs)
        return 0, "review", ""

    claude_module.run_reaped = capture_env
    try:
        provider.run("P")
    finally:
        claude_module.run_reaped = original_run_reaped
        for name, value in saved_scrubbed.items():
            if value is None:
                os.environ.pop(name, None)
            else:
                os.environ[name] = value
        if saved_sentinel is None:
            os.environ.pop("CREW_TEST_SENTINEL", None)
        else:
            os.environ["CREW_TEST_SENTINEL"] = saved_sentinel
        if saved_plugin_root is None:
            os.environ.pop("CLAUDE_PLUGIN_ROOT", None)
        else:
            os.environ["CLAUDE_PLUGIN_ROOT"] = saved_plugin_root
    child_env = env_capture.get("env", {})
    check("claude child env scrubs every captured harness marker",
          all(name not in child_env for name in claude_module._SCRUBBED_ENV_NAMES)
          and "CREW_HOST" not in child_env
          and child_env.get("CREW_TEST_SENTINEL") == "kept"
          and child_env.get("CLAUDE_PLUGIN_ROOT") == "/plugin/root",
          "scrubbed markers absent; sentinel and plugin root retained",
          repr({name: child_env.get(name) for name in claude_module._SCRUBBED_ENV_NAMES})
          + f" sentinel={child_env.get('CREW_TEST_SENTINEL')!r}")

    marker_name = "FAKE_CODEX_HOST_MARKER"
    original_marker_accessor = channels.codex_host_markers
    saved_marker_value = os.environ.get(marker_name)
    channels.codex_host_markers = lambda: (marker_name,)
    os.environ[marker_name] = "codex-marker"
    marker_env: dict = {}
    claude_module.run_reaped = lambda argv, **kwargs: (
        marker_env.update(kwargs) or (0, "review", "")
    )
    try:
        provider.run("P")
    finally:
        claude_module.run_reaped = original_run_reaped
        channels.codex_host_markers = original_marker_accessor
        if saved_marker_value is None:
            os.environ.pop(marker_name, None)
        else:
            os.environ[marker_name] = saved_marker_value
    check("claude child env also scrubs populated Codex markers",
          marker_name not in marker_env.get("env", {}),
          f"{marker_name} absent", repr(marker_env.get("env", {})))

    workspace_write = provider.run("P", sandbox="workspace-write")
    check("claude workspace-write is refused explicitly",
          workspace_write.ok is False
          and workspace_write.error == "claude seat does not support workspace-write in this build",
          "pinned workspace-write refusal", repr(workspace_write))

    with tempfile.TemporaryDirectory() as td:
        d = Path(td)
        old_path = os.environ["PATH"]
        os.environ["PATH"] = str(d)
        try:
            absent = provider.is_available()
            make_fake_bin(d, "claude", "import sys\n")
            present = provider.is_available()
        finally:
            os.environ["PATH"] = old_path
    check("claude is_available returns the tuple contract",
          absent == (False, "claude not found on PATH") and present == (True, ""),
          "(False, diagnostic) and (True, '')", repr((absent, present)))


# =============================================================================
# CodexProvider continuation tests (fake `codex` with a capability probe +
# JSONL thread-id stream). The fake distinguishes the non-billable --help probe
# from a real run, and every stream/exit knob rides an env var so one fake
# covers fresh capture, exact resume, mismatch, and every degraded path.
# =============================================================================

_CODEX_CONTINUATION_FAKE = '''
import sys, json, os

args = sys.argv[1:]

# Probe path: EVERY --help invocation is the non-billable capability probe. It
# runs no model turn; a test proves that by asserting the probe log holds only
# --help argv while the real-run capture is written exactly once.
if "--help" in args:
    probe_log = os.environ.get("FAKE_PROBE_LOG")
    if probe_log:
        with open(probe_log, "a") as f:
            f.write(" ".join(args) + "\\n")
    if args[:2] == ["exec", "resume"]:
        # `codex exec resume --help`: the resume subcommand's own help. A binary
        # without the subcommand exits nonzero (FAKE_NO_RESUME models that).
        sys.exit(2 if os.environ.get("FAKE_NO_RESUME") else 0)
    # `codex exec --help`: lists --json unless FAKE_NO_JSON suppresses it.
    text = "usage: codex exec\\n"
    if not os.environ.get("FAKE_NO_JSON"):
        text += "  --json  emit JSONL events\\n"
    sys.stdout.write(text)
    sys.exit(0)

# Real run: capture argv + stdin for assertions.
stdin = sys.stdin.read()
with open(CAPTURE, "w") as f:
    json.dump({"args": args, "stdin": stdin}, f)

if os.environ.get("FAKE_SLEEP"):
    import time
    time.sleep(float(os.environ["FAKE_SLEEP"]))

# Clean final agent message goes to the -o file (never stdout), unless empty.
out = None
for i, a in enumerate(args):
    if a == "-o":
        out = args[i + 1]
if out and not os.environ.get("FAKE_EMPTY_OUTPUT"):
    with open(out, "w") as f:
        f.write(os.environ.get("FAKE_FINAL", "CODEX EDIT DONE"))

# JSONL event stream on stdout (parsed for the first thread.started thread_id).
if "FAKE_STDOUT" in os.environ:
    sys.stdout.write(os.environ["FAKE_STDOUT"])
else:
    tid = os.environ.get("FAKE_THREAD_ID", "thread-xyz")
    sys.stdout.write(json.dumps({"type": "thread.started", "thread_id": tid}) + "\\n")
    sys.stdout.write(json.dumps({"type": "item.completed", "text": "done"}) + "\\n")

if os.environ.get("FAKE_STDERR"):
    sys.stderr.write(os.environ["FAKE_STDERR"])

sys.exit(int(os.environ.get("FAKE_EXIT", "0")))
'''


def _run_codex_with_fake(*, continuation, sandbox="workspace-write", model="o3",
                         dispatch_options=None, timeout=10, env_extra=None,
                         prompt="PROMPT-BODY"):
    """Drive CodexProvider.run() against the continuation fake; return (res, cap).

    ``cap`` is the decoded {args, stdin} the real run captured, or None if the
    seat never reached a real invocation (e.g. it was killed on timeout)."""
    from multiagent.providers import codex as codex_mod
    codex_mod._reset_probe_cache_for_tests()
    prov = codex_mod.CodexProvider(name="codex", default_model=model,
                                   reasoning_effort="xhigh")
    with tempfile.TemporaryDirectory() as td:
        d = Path(td)
        capture = d / "capture.json"
        full = f"CAPTURE = {str(capture)!r}\n" + _CODEX_CONTINUATION_FAKE
        make_fake_bin(d, "codex", full)
        env_path = os.environ["PATH"]
        os.environ["PATH"] = str(d) + os.pathsep + env_path
        saved = {}
        if env_extra:
            for k, v in env_extra.items():
                saved[k] = os.environ.get(k)
                os.environ[k] = v
        try:
            res = prov.run(prompt, sandbox=sandbox, model=model, timeout=timeout,
                           dispatch_options=dispatch_options, continuation=continuation)
        finally:
            os.environ["PATH"] = env_path
            for k, v in (saved or {}).items():
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
        cap = json.loads(capture.read_text()) if capture.exists() else None
        return res, cap


def test_codex_continuation():
    log_section("CodexProvider continuation (fake codex + capability probe)")

    # Fresh chained supported run: parse thread.started.thread_id, use -o.
    res, cap = _run_codex_with_fake(
        continuation=ProviderContinuation(), env_extra={"FAKE_THREAD_ID": "thread-xyz"})
    check("fresh chained run: ok + output from -o (not stdout JSONL)",
          res.ok and res.output == "CODEX EDIT DONE",
          "ok=True 'CODEX EDIT DONE'", f"ok={res.ok} {res.output!r}")
    check("fresh chained run: argv carries --json, no resume, never --last",
          "--json" in cap["args"] and "resume" not in cap["args"]
          and "--last" not in cap["args"],
          "--json, no resume/--last", str(cap["args"]))
    check("fresh chained run: prompt still delivered via stdin (- positional)",
          cap["stdin"] == "PROMPT-BODY" and cap["args"][1] == "-",
          "stdin prompt, leading -", f"{cap['stdin']!r} {cap['args'][:2]}")
    o = res.continuation
    check("fresh chained run: capability=supported phase=fresh id captured failure=none",
          o is not None and o.capability == "supported" and o.phase == "fresh"
          and o.conversation_id == "thread-xyz" and o.failure == "none",
          "supported/fresh/thread-xyz/none",
          repr(o))
    check("fresh chained run: flat continuation_id mirrors the structured id",
          res.continuation_id == "thread-xyz", "thread-xyz", repr(res.continuation_id))

    # Resume supported run with the EXACT supplied id (never --last).
    res, cap = _run_codex_with_fake(
        continuation=ProviderContinuation("thread-abc"),
        dispatch_options={"profile": "myprof"},
        env_extra={"FAKE_THREAD_ID": "thread-abc"})
    args = cap["args"]
    check("resume run: argv uses `resume <exact-id>`, prompt `-` last, never --last",
          "resume" in args and "thread-abc" in args
          and args[args.index("resume") + 1] == "thread-abc"
          and args[-1] == "-" and "--last" not in args,
          "resume thread-abc ... -", str(args))
    check("resume run: outer sandbox/model/reasoning/profile present BEFORE resume",
          args.index("--sandbox") < args.index("resume")
          and args.index("--model") < args.index("resume")
          and "workspace-write" in args and "o3" in args
          and "model_reasoning_effort=xhigh" in args
          and args.index("--profile") < args.index("resume") and "myprof" in args,
          "outer options before resume", str(args))
    o = res.continuation
    check("resume run: confirmed id -> phase=resume failure=none, persisted",
          res.ok and o.phase == "resume" and o.conversation_id == "thread-abc"
          and o.failure == "none" and res.continuation_id == "thread-abc",
          "resume/thread-abc/none persisted", f"{repr(o)} id={res.continuation_id!r}")

    # Option-like resume IDs fail before any resume subprocess is invoked.
    res, cap = _run_codex_with_fake(continuation=ProviderContinuation("--last"))
    resume_args = cap["args"] if cap else []
    o = res.continuation
    check("option-like resume ID: no bare --last argv and resume fails closed",
          res.ok is False and not cap and "--last" not in resume_args
          and o is not None and o.phase == "resume"
          and o.failure == "error" and o.conversation_id is None
          and res.continuation_id is None,
          "no run, resume/error/None", f"ok={res.ok} cap={cap!r} outcome={o!r}")

    res, cap = _run_codex_with_fake(continuation=ProviderContinuation("   "))
    o = res.continuation
    check("whitespace-only resume ID: rejected before subprocess invocation",
          res.ok is False and not cap
          and o is not None and o.phase == "resume"
          and o.failure == "error" and o.conversation_id is None
          and res.continuation_id is None,
          "no run, resume/error/None", f"ok={res.ok} cap={cap!r} outcome={o!r}")

    for captured_id in ("   ", "--captured"):
        res, cap = _run_codex_with_fake(
            continuation=ProviderContinuation(),
            env_extra={"FAKE_THREAD_ID": captured_id},
        )
        o = res.continuation
        status = continuations.classify_continuation(None, True, True, o)
        check(
            "invalid captured thread ID is unavailable and not persisted",
            res.ok and cap is not None and o is not None
            and o.conversation_id is None and res.continuation_id is None
            and status == ("unavailable", "keep"),
            "unavailable/keep with no conversation ID",
            f"captured={captured_id!r} outcome={o!r} status={status!r}",
        )

    # Resume id MISMATCH: hard continuation failure, id never persisted.
    res, cap = _run_codex_with_fake(
        continuation=ProviderContinuation("thread-abc"),
        env_extra={"FAKE_THREAD_ID": "thread-DIFFERENT"})
    o = res.continuation
    check("resume mismatch: ok stays True (edits kept) but failure=error, id NOT persisted",
          res.ok and o.phase == "resume" and o.failure == "error"
          and o.conversation_id == "thread-DIFFERENT" and res.continuation_id is None,
          "ok/resume/error/mismatched, no persist",
          f"{repr(o)} id={res.continuation_id!r}")

    # JSONL robustness: malformed + unknown + duplicate -> first valid wins.
    noisy = (
        "this is not json\n"
        + json.dumps({"type": "session.meta"}) + "\n"
        + json.dumps({"type": "thread.started"}) + "\n"          # no thread_id
        + json.dumps({"type": "thread.started", "thread_id": "first"}) + "\n"
        + json.dumps({"type": "thread.started", "thread_id": "second"}) + "\n"
    )
    res, cap = _run_codex_with_fake(
        continuation=ProviderContinuation(), env_extra={"FAKE_STDOUT": noisy})
    check("noisy JSONL: malformed/unknown/id-less skipped, FIRST valid id wins",
          res.continuation.conversation_id == "first", "first", repr(res.continuation))

    # Fresh run that emits NO thread id: capability supported, id None.
    res, cap = _run_codex_with_fake(
        continuation=ProviderContinuation(),
        env_extra={"FAKE_STDOUT": json.dumps({"type": "item.completed"}) + "\n"})
    o = res.continuation
    check("fresh, no id emitted: supported/fresh, conversation_id None, not persisted",
          res.ok and o.capability == "supported" and o.conversation_id is None
          and o.failure == "none" and res.continuation_id is None,
          "supported/fresh/None", f"{repr(o)} id={res.continuation_id!r}")

    # Nonzero exit: diagnostic preserved, failure=error.
    res, cap = _run_codex_with_fake(
        continuation=ProviderContinuation(),
        env_extra={"FAKE_EXIT": "1", "FAKE_STDERR": "not authenticated"})
    o = res.continuation
    check("nonzero exit: ok=False, stderr in error, failure=error, not persisted",
          res.ok is False and res.error and "not authenticated" in res.error
          and o.failure == "error" and res.continuation_id is None,
          "ok=False/error/no persist", f"ok={res.ok} err={res.error!r} {repr(o)}")

    res, cap = _run_codex_with_fake(
        continuation=ProviderContinuation(), env_extra={"FAKE_EXIT": "1"})
    check(
        "capable nonzero exit with empty stderr: JSONL is not used as the error",
        res.error == "codex exited with status 1"
        and "thread-xyz" not in res.error
        and "thread.started" not in res.error,
        "status-only diagnostic without raw JSONL or thread ID",
        repr(res.error),
    )

    # Timeout: failure=timeout (distinguished at the reaper, not string-parsed).
    res, cap = _run_codex_with_fake(
        continuation=ProviderContinuation(), timeout=1,
        env_extra={"FAKE_SLEEP": "10"})
    o = res.continuation
    check("timeout: ok=False, timeout error, continuation failure=timeout",
          res.ok is False and res.error and "timed out" in res.error
          and o is not None and o.failure == "timeout" and o.conversation_id is None,
          "ok=False/timeout", f"ok={res.ok} {repr(o)}")

    # Empty final output at exit 0: failure=error (not a delta fallback).
    res, cap = _run_codex_with_fake(
        continuation=ProviderContinuation(), env_extra={"FAKE_EMPTY_OUTPUT": "1"})
    o = res.continuation
    check("empty -o output at exit 0: ok=False, no-output error, failure=error",
          res.ok is False and res.error and "no output" in res.error
          and o.failure == "error", "ok=False/error", f"ok={res.ok} {repr(o)}")

    # Unsupported binary (probe fails) -> runs FRESH, reports unsupported.
    for knob, label in (({"FAKE_NO_RESUME": "1"}, "no exec resume"),
                        ({"FAKE_NO_JSON": "1"}, "no --json in help")):
        res, cap = _run_codex_with_fake(
            continuation=ProviderContinuation("thread-abc"), env_extra=knob)
        o = res.continuation
        check(f"unsupported ({label}): fresh argv (no --json/resume), capability=unsupported",
              res.ok and "--json" not in cap["args"] and "resume" not in cap["args"]
              and o.capability == "unsupported" and o.phase == "fresh"
              and o.conversation_id is None and res.continuation_id is None,
              "fresh/unsupported", f"{repr(o)} args={cap['args']}")

    # An OSError during probing falls back to a fresh run and cleans -o.
    from multiagent.providers import codex as codex_mod
    codex_mod._reset_probe_cache_for_tests()
    with tempfile.TemporaryDirectory() as td:
        d = Path(td)
        capture = d / "capture.json"
        full = f"CAPTURE = {str(capture)!r}\n" + _CODEX_CONTINUATION_FAKE
        make_fake_bin(d, "codex", full)
        env_path = os.environ["PATH"]
        os.environ["PATH"] = str(d) + os.pathsep + env_path
        created_paths = []
        run_calls = 0
        original_mkstemp = codex_mod.tempfile.mkstemp
        original_run_reaped = codex_mod.run_reaped

        def tracking_mkstemp(*args, **kwargs):
            result = original_mkstemp(*args, **kwargs)
            created_paths.append(result[1])
            return result

        def probe_oserror_then_run(*args, **kwargs):
            nonlocal run_calls
            run_calls += 1
            if run_calls == 1:
                raise OSError("codex vanished after which")
            return original_run_reaped(*args, **kwargs)

        codex_mod.tempfile.mkstemp = tracking_mkstemp
        codex_mod.run_reaped = probe_oserror_then_run
        try:
            prov = codex_mod.CodexProvider(name="codex", default_model="o3")
            res = prov.run(
                "P", sandbox="workspace-write", timeout=10,
                continuation=ProviderContinuation("thread-abc"),
            )
        finally:
            codex_mod.tempfile.mkstemp = original_mkstemp
            codex_mod.run_reaped = original_run_reaped
            os.environ["PATH"] = env_path
        o = res.continuation
        real_cap = json.loads(capture.read_text()) if capture.exists() else {}
        check("probe OSError: fresh unsupported run completes without resume",
              run_calls == 2 and res.ok and o is not None
              and o.capability == "unsupported" and o.phase == "fresh"
              and "resume" not in real_cap.get("args", []),
              "fresh unsupported run", f"calls={run_calls} outcome={o!r} cap={real_cap}")
        check("probe OSError: output temp file is cleaned up",
              bool(created_paths) and all(not Path(path).exists() for path in created_paths),
              "no created temp path remains", repr(created_paths))

    # Probe is NON-BILLABLE: only --help argv reaches it, real run once.
    codex_mod._reset_probe_cache_for_tests()
    with tempfile.TemporaryDirectory() as td:
        d = Path(td)
        capture = d / "capture.json"
        probe_log = d / "probe.log"
        full = f"CAPTURE = {str(capture)!r}\n" + _CODEX_CONTINUATION_FAKE
        make_fake_bin(d, "codex", full)
        env_path = os.environ["PATH"]
        os.environ["PATH"] = str(d) + os.pathsep + env_path
        os.environ["FAKE_PROBE_LOG"] = str(probe_log)
        try:
            prov = codex_mod.CodexProvider(name="codex", default_model="o3",
                                           reasoning_effort="xhigh")
            prov.run("P", sandbox="workspace-write", model="o3", timeout=10,
                     continuation=ProviderContinuation())
        finally:
            os.environ["PATH"] = env_path
            os.environ.pop("FAKE_PROBE_LOG", None)
        probe_lines = probe_log.read_text().splitlines() if probe_log.exists() else []
        check("probe is non-billable: every probe invocation is a --help call",
              probe_lines and all("--help" in ln for ln in probe_lines),
              "all --help", str(probe_lines))

    # Per-process probe memo: a second run on the same binary re-uses it.
    codex_mod._reset_probe_cache_for_tests()
    with tempfile.TemporaryDirectory() as td:
        d = Path(td)
        capture = d / "capture.json"
        probe_log = d / "probe.log"
        full = f"CAPTURE = {str(capture)!r}\n" + _CODEX_CONTINUATION_FAKE
        make_fake_bin(d, "codex", full)
        env_path = os.environ["PATH"]
        os.environ["PATH"] = str(d) + os.pathsep + env_path
        os.environ["FAKE_PROBE_LOG"] = str(probe_log)
        try:
            prov = codex_mod.CodexProvider(name="codex", default_model="o3")
            prov.run("P", sandbox="workspace-write", timeout=10,
                     continuation=ProviderContinuation())
            first = probe_log.read_text().count("\n") if probe_log.exists() else 0
            prov.run("P", sandbox="workspace-write", timeout=10,
                     continuation=ProviderContinuation())
            second = probe_log.read_text().count("\n") if probe_log.exists() else 0
        finally:
            os.environ["PATH"] = env_path
            os.environ.pop("FAKE_PROBE_LOG", None)
        check("probe memoized per binary path: second run adds NO probe calls",
              first > 0 and second == first, f"{first}=={second}",
              f"first={first} second={second}")

    # Read-only + continuation passed (defensive): argv unchanged, no outcome.
    res, cap = _run_codex_with_fake(
        continuation=ProviderContinuation("thread-abc"), sandbox="read-only")
    check("read-only ignores continuation: --ignore-user-config kept, no --json/resume, no outcome",
          "--ignore-user-config" in cap["args"] and "--json" not in cap["args"]
          and "resume" not in cap["args"] and res.continuation is None
          and res.continuation_id is None,
          "read-only argv unchanged, no outcome", f"{cap['args']} cont={res.continuation!r}")

    # Unchained workspace-write argv stays byte-for-byte the legacy shape.
    res, cap = _run_codex_with_fake(continuation=None, sandbox="workspace-write")
    expected = ["exec", "-", "-c", "model_reasoning_effort=xhigh", "--sandbox",
                "workspace-write", "--model", "o3", "--skip-git-repo-check", "-o"]
    check("unchained workspace-write: argv byte-identical to legacy, no outcome",
          cap["args"][:-1] == expected and res.continuation is None
          and res.continuation_id is None,
          "legacy write argv + no outcome", str(cap["args"]))


# =============================================================================
# CursorProvider continuation tests (fake `agent` with a capability probe and
# stream-JSON session events).
# =============================================================================

_CURSOR_CONTINUATION_FAKE = '''
import json, os, sys

args = sys.argv[1:]

if "--version" in args:
    print("2026.07.20-00-00-00-test")
    sys.exit(0)

if "--help" in args:
    probe_log = os.environ.get("FAKE_PROBE_LOG")
    if probe_log:
        with open(probe_log, "a") as f:
            f.write(" ".join(args) + "\\n")
    text = "usage: agent [options]\\n"
    if not os.environ.get("FAKE_NO_RESUME"):
        text += "  --resume <chatId>\\n"
    if not os.environ.get("FAKE_NO_OUTPUT_FORMAT"):
        text += "  --output-format <format>\\n"
    if not os.environ.get("FAKE_NO_STREAM_JSON"):
        text += "  stream-json\\n"
    sys.stdout.write(text)
    sys.exit(0)

with open(CAPTURE, "w") as f:
    json.dump({"args": args, "cwd": os.getcwd()}, f)

if os.environ.get("FAKE_SLEEP"):
    import time
    time.sleep(float(os.environ["FAKE_SLEEP"]))

if "--output-format" in args:
    if "FAKE_STDOUT" in os.environ:
        stdout = os.environ["FAKE_STDOUT"]
    else:
        session_id = os.environ.get("FAKE_SESSION_ID", "cursor-session-xyz")
        stdout = (
            json.dumps({"type": "system", "subtype": "init",
                        "session_id": session_id}) + "\\n"
            + json.dumps({"type": "result", "subtype": "success",
                          "is_error": False, "result": "CURSOR EDIT DONE",
                          "session_id": session_id}) + "\\n"
        )
else:
    stdout = "CURSOR LEGACY OUTPUT"
sys.stdout.write(stdout)

if os.environ.get("FAKE_STDERR"):
    sys.stderr.write(os.environ["FAKE_STDERR"])

sys.exit(int(os.environ.get("FAKE_EXIT", "0")))
'''


def _run_cursor_with_fake(*, continuation, sandbox="workspace-write", model="m1",
                          dispatch_options=None, timeout=10, env_extra=None,
                          prompt="PROMPT-BODY"):
    """Drive CursorProvider.run() against the continuation fake."""
    from multiagent.providers import cursor as cursor_mod
    cursor_mod._reset_probe_cache_for_tests()
    prov = cursor_mod.CursorProvider(name="cursor-test", default_model=model)
    with tempfile.TemporaryDirectory() as td:
        d = Path(td)
        capture = d / "capture.json"
        full = f"CAPTURE = {str(capture)!r}\n" + _CURSOR_CONTINUATION_FAKE
        make_fake_bin(d, "agent", full)
        env_path = os.environ["PATH"]
        os.environ["PATH"] = str(d) + os.pathsep + env_path
        saved = {}
        if env_extra:
            for k, v in env_extra.items():
                saved[k] = os.environ.get(k)
                os.environ[k] = v
        try:
            res = prov.run(prompt, sandbox=sandbox, model=model, timeout=timeout,
                           dispatch_options=dispatch_options, continuation=continuation)
        finally:
            os.environ["PATH"] = env_path
            for k, v in saved.items():
                if v is None:
                    os.environ.pop(k, None)
                else:
                    os.environ[k] = v
        cap = json.loads(capture.read_text()) if capture.exists() else None
        return res, cap


def test_cursor_continuation():
    log_section("CursorProvider continuation (fake agent + capability probe)")

    res, cap = _run_cursor_with_fake(
        continuation=ProviderContinuation(),
        env_extra={"FAKE_SESSION_ID": "cursor-session-xyz"},
    )
    check("fresh chained run: terminal result.result becomes output",
          res.ok and res.output == "CURSOR EDIT DONE",
          "ok=True 'CURSOR EDIT DONE'", f"ok={res.ok} output={res.output!r}")
    check("fresh chained run: stream-json is continuation-only",
          cap is not None and "--output-format" in cap["args"]
          and cap["args"][cap["args"].index("--output-format") + 1] == "stream-json"
          and cap["args"][-1] == "PROMPT-BODY",
          "--output-format stream-json, prompt last", str(cap))
    outcome = res.continuation
    check("fresh chained run: init session_id captured and persisted",
          outcome is not None and outcome.capability == "supported"
          and outcome.phase == "fresh" and outcome.conversation_id == "cursor-session-xyz"
          and outcome.failure == "none" and res.continuation_id == "cursor-session-xyz",
          "supported/fresh/cursor-session-xyz/none",
          f"outcome={outcome!r} id={res.continuation_id!r}")

    with tempfile.TemporaryDirectory() as td:
        from multiagent.providers import cursor as cursor_mod
        cursor_mod._reset_probe_cache_for_tests()
        d = Path(td)
        capture = d / "capture.json"
        probe_log = d / "probe.log"
        make_fake_bin(d, "agent", f"CAPTURE = {str(capture)!r}\n" + _CURSOR_CONTINUATION_FAKE)
        env_path = os.environ["PATH"]
        os.environ["PATH"] = str(d) + os.pathsep + env_path
        old_probe_log = os.environ.get("FAKE_PROBE_LOG")
        os.environ["FAKE_PROBE_LOG"] = str(probe_log)
        try:
            prov = cursor_mod.CursorProvider(name="cursor-test", default_model="m1")
            res = prov.run("PROMPT-BODY", sandbox="workspace-write", timeout=10,
                           continuation=ProviderContinuation())
            first = probe_log.read_text().splitlines() if probe_log.exists() else []
            res2 = prov.run("PROMPT-BODY", sandbox="workspace-write", timeout=10,
                            continuation=ProviderContinuation())
            second = probe_log.read_text().splitlines() if probe_log.exists() else []
        finally:
            os.environ["PATH"] = env_path
            if old_probe_log is None:
                os.environ.pop("FAKE_PROBE_LOG", None)
            else:
                os.environ["FAKE_PROBE_LOG"] = old_probe_log
        check("capability probe: help is non-billable and requires all stream flags",
              first and all("--help" in line for line in first)
              and any("--help" in line for line in first)
              and res.ok and res2.ok,
              "help-only probe and successful runs", str(first))
        check("capability probe: memoized per resolved binary path",
              len(second) == len(first), f"{len(first)} probe calls", str(second))

    res, cap = _run_cursor_with_fake(
        continuation=ProviderContinuation("cursor-session-abc"),
        dispatch_options={"force": True, "approve_mcps": True},
        env_extra={"FAKE_SESSION_ID": "cursor-session-abc"},
    )
    args = cap["args"]
    resume_index = args.index("--resume")
    check("resume run: exact ID, no --continue, prompt remains final positional",
          args[resume_index + 1] == "cursor-session-abc"
          and "--continue" not in args and args[-1] == "PROMPT-BODY",
          "--resume cursor-session-abc ... PROMPT-BODY", str(args))
    check("resume run: workspace/model/sandbox/trust/force/MCP options remain",
          "--sandbox" in args and "enabled" in args and "--trust" in args
          and "--workspace" in args and "--model" in args and "m1" in args
          and "--force" in args and "--approve-mcps" in args
          and args.index("--resume") < args.index("--sandbox"),
          "all outer options retained", str(args))
    outcome = res.continuation
    check("resume run: confirmed ID produces successful resume outcome",
          res.ok and outcome is not None and outcome.phase == "resume"
          and outcome.conversation_id == "cursor-session-abc"
          and outcome.failure == "none" and res.continuation_id == "cursor-session-abc",
          "ok/resume/confirmed ID/none", f"{outcome!r} id={res.continuation_id!r}")

    noisy = (
        "not json\n"
        + json.dumps({"type": "unknown", "session_id": "ignored"}) + "\n"
        + json.dumps({"type": "system", "subtype": "init",
                      "session_id": "cursor-noisy"}) + "\n"
        + json.dumps({"type": "assistant", "delta": {"text": "PART "},
                      "session_id": "cursor-noisy"}) + "\n"
        + json.dumps({"type": "result", "subtype": "success", "is_error": False,
                      "result": "DONE",
                      "session_id": "cursor-noisy"}) + "\n"
    )
    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation(), env_extra={"FAKE_STDOUT": noisy})
    check("stream parser: malformed and unknown events do not traceback",
          res.ok and res.output == "DONE" and res.continuation_id == "cursor-noisy",
          "successful parsed result", f"{res!r}")

    mismatched = (
        json.dumps({"type": "system", "subtype": "init",
                    "session_id": "cursor-session-abc"}) + "\n"
        + json.dumps({"type": "assistant", "delta": "partial",
                      "session_id": "cursor-session-other"}) + "\n"
        + json.dumps({"type": "result", "subtype": "success", "is_error": False,
                      "result": "DONE",
                      "session_id": "cursor-session-abc"}) + "\n"
    )
    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation("cursor-session-abc"),
        env_extra={"FAKE_STDOUT": mismatched},
    )
    outcome = res.continuation
    check("mismatched later ID: edits kept, continuation fails, ID not persisted",
          res.ok and outcome is not None and outcome.failure == "error"
          and res.continuation_id is None,
          "ok=True/failure=error/no persisted ID", f"{res!r}")

    non_assistant_mismatch = (
        json.dumps({"type": "system", "subtype": "init",
                    "session_id": "cursor-session-abc"}) + "\n"
        + json.dumps({"type": "user", "message": "input",
                      "session_id": "cursor-session-other"}) + "\n"
        + json.dumps({"type": "result", "subtype": "success", "is_error": False,
                      "result": "DONE",
                      "session_id": "cursor-session-abc"}) + "\n"
    )
    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation("cursor-session-abc"),
        env_extra={"FAKE_STDOUT": non_assistant_mismatch},
    )
    outcome = res.continuation
    check("mismatched non-assistant ID: continuation fails without persistence",
          res.ok and res.output == "DONE" and outcome is not None
          and outcome.phase == "resume" and outcome.failure == "error"
          and res.continuation_id is None,
          "ok=True/resume/failure=error/no persisted ID", f"{res!r}")

    missing_id = json.dumps({"type": "result", "subtype": "success", "is_error": False,
                             "result": "DONE"}) + "\n"
    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation("cursor-session-abc"),
        env_extra={"FAKE_STDOUT": missing_id},
    )
    outcome = res.continuation
    check("resume without confirmed init ID: hard failure and no persistence",
          res.ok and outcome is not None and outcome.phase == "resume"
          and outcome.failure == "error" and outcome.conversation_id is None
          and res.continuation_id is None,
          "ok=True/resume/error/None", f"{res!r}")

    delta_stream = (
        json.dumps({"type": "system", "subtype": "init",
                    "session_id": "cursor-delta"}) + "\n"
        + json.dumps({"type": "assistant", "delta": "one",
                      "session_id": "cursor-delta"}) + "\n"
        + json.dumps({"type": "assistant", "delta": {"text": " two"},
                      "session_id": "cursor-delta"}) + "\n"
    )
    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation(), env_extra={"FAKE_STDOUT": delta_stream})
    outcome = res.continuation
    check("missing terminal result: deltas remain displayable without persistence",
          res.ok and res.output == "one two" and outcome is not None
          and outcome.failure == "error" and res.continuation_id is None,
          "ok=True 'one two'/failure=error/no ID", f"{res!r}")

    message_stream = (
        json.dumps({"type": "system", "subtype": "init",
                    "session_id": "cursor-message"}) + "\n"
        + json.dumps({"type": "assistant", "message": {
            "role": "assistant",
            "content": [{"type": "text", "text": "canonical "},
                        {"type": "text", "text": "message"}],
        }, "session_id": "cursor-message"}) + "\n"
    )
    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation(), env_extra={"FAKE_STDOUT": message_stream})
    outcome = res.continuation
    check("missing terminal result: message fallback does not advance chain",
          res.ok and res.output == "canonical message" and outcome is not None
          and outcome.failure == "error" and res.continuation_id is None,
          "ok=True 'canonical message'/failure=error/no ID", f"{res!r}")

    for label, result_fields in (
        ("non-success subtype", {"subtype": "error", "is_error": False}),
        ("error flag", {"subtype": "success", "is_error": True}),
        ("missing subtype", {"is_error": False}),
        ("missing error flag", {"subtype": "success"}),
    ):
        terminal = {"type": "result", "result": "DISPLAY ONLY", **result_fields}
        status_stream = (
            json.dumps({"type": "system", "subtype": "init",
                        "session_id": "cursor-status"}) + "\n"
            + json.dumps(terminal) + "\n"
        )
        res, _ = _run_cursor_with_fake(
            continuation=ProviderContinuation(), env_extra={"FAKE_STDOUT": status_stream})
        outcome = res.continuation
        check(f"terminal {label}: no continuation persistence",
              outcome is not None and outcome.failure == "error"
              and res.continuation_id is None,
              "failure=error/no ID", f"{res!r}")

    empty_stream = json.dumps({"type": "system", "subtype": "init",
                               "session_id": "cursor-empty"}) + "\n"
    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation(), env_extra={"FAKE_STDOUT": empty_stream})
    outcome = res.continuation
    check("empty stream: exit 0 is a failure, not a delta fallback",
          res.ok is False and outcome is not None and outcome.failure == "error"
          and "empty" in (res.error or "").lower(),
          "ok=False/failure=error/empty diagnostic", f"{res!r}")

    empty_result = (
        json.dumps({"type": "system", "subtype": "init",
                    "session_id": "cursor-empty-result"}) + "\n"
        + json.dumps({"type": "assistant", "delta": "do not use",
                      "session_id": "cursor-empty-result"}) + "\n"
        + json.dumps({"type": "result", "subtype": "success", "is_error": False,
                      "result": "",
                      "session_id": "cursor-empty-result"}) + "\n"
    )
    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation(), env_extra={"FAKE_STDOUT": empty_result})
    outcome = res.continuation
    check("empty terminal result: failure, no assistant-delta fallback",
          res.ok is False and res.output == "" and outcome is not None
          and outcome.failure == "error" and res.continuation_id is None,
          "ok=False/empty output/no persistence", f"{res!r}")

    auth_stream = (
        json.dumps({"type": "system", "subtype": "init",
                    "session_id": "cursor-auth"}) + "\n"
        + json.dumps({"type": "result", "subtype": "success",
                      "is_error": False,
                      "result": "\x1b[31msign in to continue\x1b[0m",
                      "session_id": "cursor-auth"}) + "\n"
    )
    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation(), env_extra={"FAKE_STDOUT": auth_stream})
    outcome = res.continuation
    check("capable exit-0 auth banner: normalized failure, no ID persistence",
          res.ok is False and "authentication required" in (res.error or "")
          and "\x1b" not in res.output and outcome is not None
          and outcome.failure == "error" and outcome.conversation_id is None
          and res.continuation_id is None,
          "ok=False/failure=error/no persisted ID", f"{res!r}")

    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation(),
        env_extra={"FAKE_EXIT": "1", "FAKE_STDERR": "backend failed"},
    )
    check("capable nonzero exit: stderr preserved, stream JSON not leaked",
          res.ok is False and "backend failed" in (res.error or "")
          and "session_id" not in (res.error or "")
          and "system" not in (res.error or ""),
          "stderr diagnostic without raw stream", repr(res.error))

    res, _ = _run_cursor_with_fake(
        continuation=ProviderContinuation(), timeout=1,
        env_extra={"FAKE_SLEEP": "10"},
    )
    outcome = res.continuation
    check("capable timeout: timeout failure and no ID persistence",
          res.ok is False and outcome is not None and outcome.failure == "timeout"
          and outcome.conversation_id is None and res.continuation_id is None,
          "ok=False/failure=timeout/no ID", f"{res!r}")

    from multiagent.providers import cursor as cursor_mod
    oversized = "x" * (cursor_mod._ARG_MAX_BYTES + 1)
    res, cap = _run_cursor_with_fake(
        continuation=ProviderContinuation("cursor-session-abc"), prompt=oversized)
    outcome = res.continuation
    check("oversized chained prompt: error outcome preserves resume phase",
          res.ok is False and cap is None and outcome is not None
          and outcome.capability == "supported" and outcome.phase == "resume"
          and outcome.failure == "error" and outcome.conversation_id is None
          and res.continuation_id is None,
          "ok=False/supported/resume/failure=error/no ID", f"{res!r}")

    res, cap = _run_cursor_with_fake(
        continuation=ProviderContinuation("cursor-session-abc"), model=None)
    outcome = res.continuation
    check("no-model chained run: error outcome preserves probed resume phase",
          res.ok is False and cap is None and outcome is not None
          and outcome.capability == "supported" and outcome.phase == "resume"
          and outcome.failure == "error" and outcome.conversation_id is None
          and res.continuation_id is None,
          "ok=False/supported/resume/failure=error/no ID", f"{res!r}")

    for captured_id in ("   ", "--captured"):
        res, _ = _run_cursor_with_fake(
            continuation=ProviderContinuation(),
            env_extra={"FAKE_SESSION_ID": captured_id},
        )
        outcome = res.continuation
        status = continuations.classify_continuation(None, True, True, outcome)
        check("invalid captured session ID is dropped and classified unavailable",
              res.ok and outcome is not None and outcome.conversation_id is None
              and outcome.failure == "none" and res.continuation_id is None
              and status == ("unavailable", "keep"),
              "failure=none, unavailable/keep, no continuation ID",
              f"{res!r} status={status!r}")

    for knob in ("FAKE_NO_RESUME", "FAKE_NO_OUTPUT_FORMAT", "FAKE_NO_STREAM_JSON"):
        res, cap = _run_cursor_with_fake(
            continuation=ProviderContinuation("cursor-session-abc"),
            env_extra={knob: "1"},
        )
        outcome = res.continuation
        check(f"unsupported help surface ({knob}): fresh run without stream or resume",
              res.ok and cap is not None and "--resume" not in cap["args"]
              and "--output-format" not in cap["args"]
              and outcome is not None and outcome.capability == "unsupported"
              and outcome.phase == "fresh" and outcome.conversation_id is None
              and res.continuation_id is None,
              "fresh/unsupported/no continuation argv", f"{res!r} args={cap}")

    res, cap = _run_cursor_with_fake(
        continuation=ProviderContinuation("cursor-session-abc"),
        sandbox="read-only", dispatch_options={"force": True, "approve_mcps": True},
    )
    args = cap["args"]
    check("read-only continuation: legacy argv unchanged and no outcome",
          args[0:3] == ["--print", "--mode", "plan"]
          and "--output-format" not in args and "--resume" not in args
          and "--force" not in args and "--approve-mcps" not in args
          and res.continuation is None and res.continuation_id is None
          and args[-1] == "PROMPT-BODY",
          "legacy read-only argv", str(args))

    res, cap = _run_cursor_with_fake(continuation=None, sandbox="workspace-write")
    args = cap["args"]
    check("unchained workspace-write: legacy argv unchanged and no outcome",
          args == ["--print", "--sandbox", "enabled", "--trust", "--workspace",
                   cap["cwd"], "--model", "m1", "PROMPT-BODY"]
          and res.continuation is None and res.continuation_id is None,
          "legacy workspace-write argv", str(cap))


