def test_build_md_continuation_wiring():
    """The build recipe resolves once, stamps init, and conditionally chains."""
    log_section("build.md continuation wiring")
    raw = (SCRIPT_DIR.parent / "commands" / "build.md").read_text(encoding="utf-8")
    fences = _fence_lines("build.md")
    resolver_index = next(
        (i for i, line in enumerate(fences) if "build-executor" in line), -1
    )
    init_index = next(
        (i for i, line in enumerate(fences) if "state init bl" in line), -1
    )
    check("build.md resolves executor before init",
          resolver_index >= 0 and init_index >= 0 and resolver_index < init_index,
          "build-executor fence before state init bl", str(fences))
    check("build.md resolve fence passes the mandatory session id",
          resolver_index >= 0 and "--session-id <session-id>" in fences[resolver_index],
          "build-executor fence with --session-id <session-id>",
          str(fences[resolver_index] if resolver_index >= 0 else fences))
    init_lines = [line for line in fences if "state init bl" in line]
    check("build.md passes resolved executor settings to init",
          len(init_lines) == 1 and "--executor <executor>" in init_lines[0]
          and "--resume-executor <true|false>" in init_lines[0],
          "one init fence with both flags", str(init_lines))

    chain_lines = [line for line in fences if "--chain build-executor" in line]
    check("build.md has one canonical external chained dispatch fence",
          len(chain_lines) == 1 and "dispatch" in chain_lines[0]
          and "--seat <executor>" in chain_lines[0],
          "one external dispatch chain fence", str(chain_lines))
    check("build.md documents dropping the chain when resume_executor is false",
          "resume_executor" in raw and "false" in raw and "omit" in raw.lower()
          and "runs fresh" in raw,
          "resume condition prose", raw[raw.find("--chain build-executor") - 100:raw.find("--chain build-executor") + 220])
    check("build.md task path remains unchained",
          len(chain_lines) == 1
          and sum("--chain" in line for line in fences) == 1,
          "only the external dispatch carries --chain", str(chain_lines))

    resolve_heading = raw.index("## MANDATORY: Resolve the Executor")
    activate_heading = raw.index("## MANDATORY: Activate the Loop")
    trailing = raw[raw.rfind("First:"):]
    check("build.md heading order is resolve before activate",
          resolve_heading < activate_heading,
          "Resolve heading before Activate heading", str((resolve_heading, activate_heading)))
    check("build.md has no activate-then-resolve directive",
          "after activation" not in raw.lower()
          and trailing.lower().find("resolve") < trailing.lower().find("activation"),
          "no after-activation directive; trailing reminder resolves first", trailing)
    check("build.md preserves user-only executor flag ownership",
          "pass `--executor <seat>` ONLY when the user named one" in raw,
          "user-only --executor instruction", raw[raw.find("Executor option"):raw.find("Executor option") + 700])


def test_workplan_contract_freeze():
    """Freeze the current review-prep JSON shape and roster partition."""
    log_section("contract freeze: review-prep work-plan JSON")
    expected_keys = [
        "prompt_path", "subprocess_seats", "task_seats", "task_seat_models",
        "run_dir", "run_id", "target_sha256", "session_segment",
        "task_prompt_paths", "pending_subprocess_seats", "pending_task_seats",
        "host", "seat_channels",
    ]
    cursor_seats = [
        "cursor-auto", "cursor-composer", "cursor-gemini", "cursor-glm",
        "cursor-gpt", "cursor-grok",
    ]
    cases = [
        (
            "default panel",
            ["review-prep", "plan.md", "--session-id", "freeze-default"],
            ["codex", "codex-luna", "agy", "cursor-auto", "cursor-composer"],
            ["opus", "sonnet"],
            {"opus": "opus", "sonnet": "sonnet"},
            {"codex": "codex", "codex-luna": "codex", "agy": "agy",
             "cursor-auto": "cursor", "cursor-composer": "cursor",
             "opus": "claude", "sonnet": "claude"},
        ),
        (
            "explicit mixed seats",
            [
                "review-prep", "plan.md", "--seats", "codex,opus",
                "--session-id", "freeze-mixed",
            ],
            ["codex"],
            ["opus"],
            {"opus": "opus"},
            {"codex": "codex", "opus": "claude"},
        ),
        (
            "task-only solo panel",
            [
                "review-prep", "plan.md", "--panel", "solo",
                "--session-id", "freeze-solo",
            ],
            [],
            ["opus"],
            {"opus": "opus"},
            {"opus": "claude"},
        ),
        (
            "external-only explicit seat",
            [
                "review-prep", "plan.md", "--seats", "codex",
                "--session-id", "freeze-external",
            ],
            ["codex"],
            [],
            {},
            {"codex": "codex"},
        ),
        (
            "external-only cursor panel",
            [
                "review-prep", "plan.md", "--panel", "cursor",
                "--session-id", "freeze-cursor",
            ],
            cursor_seats,
            [],
            {},
            {name: "cursor" for name in cursor_seats},
        ),
    ]

    for (label, args, expected_subprocess, expected_task, expected_models,
         expected_channels) in cases:
        with tempfile.TemporaryDirectory() as td:
            _write_plan(Path(td))
            proc = _run_dispatcher(
                args, cwd=td, env=_clean_env(td), timeout=30,
            )
            try:
                payload = json.loads(proc.stdout)
            except json.JSONDecodeError as exc:
                payload = None
                check(
                    f"{label}: review-prep emits JSON",
                    False,
                    "valid JSON",
                    f"{exc}: rc={proc.returncode} stdout={proc.stdout[:160]!r}",
                )
            if payload is not None:
                check(
                    f"{label}: review-prep exact key order and exit 0",
                    proc.returncode == 0 and list(payload) == expected_keys,
                    str(expected_keys),
                    f"rc={proc.returncode} keys={list(payload)}",
                )
                check(
                    f"{label}: review-prep exact seat partition",
                    payload["subprocess_seats"] == expected_subprocess
                    and payload["task_seats"] == expected_task
                    and payload["task_seat_models"] == expected_models,
                    f"subprocess={expected_subprocess}, task={expected_task}, models={expected_models}",
                    f"subprocess={payload.get('subprocess_seats')}, "
                    f"task={payload.get('task_seats')}, models={payload.get('task_seat_models')}",
                )
                check(
                    f"{label}: host and final roster channel map",
                    payload["host"] == "claude"
                    and payload["seat_channels"] == expected_channels
                    and set(payload["seat_channels"]) == set(
                        expected_subprocess + expected_task),
                    f"host='claude', seat_channels={expected_channels}",
                    f"host={payload.get('host')!r}, channels={payload.get('seat_channels')}",
                )

    # An opaque task override is deliberately not a catalog lookup: its channel
    # provenance is the current host's native channel, while the name remains
    # exactly the caller-supplied roster member.
    with tempfile.TemporaryDirectory() as td:
        _write_plan(Path(td))
        proc = _run_dispatcher(
            ["review-prep", "plan.md", "--seats", "", "--task-seats", "opaque-task",
             "--session-id", "freeze-opaque"],
            cwd=td, env=_clean_env(td), timeout=30,
        )
        payload = json.loads(proc.stdout) if proc.stdout.strip() else {}
        check(
            "opaque task override maps to the current host native channel",
            proc.returncode == 0
            and payload.get("task_seats") == ["opaque-task"]
            and payload.get("seat_channels") == {"opaque-task": "claude"},
            "task=['opaque-task'], channel=claude",
            f"rc={proc.returncode} payload={payload}",
        )


