def _swab_run(project_dir, *, yes=False, as_json=False, cwd=None, project_env=True):
    """Invoke cmd_swab in-process against ``project_dir`` (env-isolated), returning
    ``(rc, stdout, stderr)``. HOME is neutralized so no real ~/.crew-config leaks.

    ``cwd`` defaults to ``project_dir``: swab resolves ``.crew`` through the shared
    ``crew_base()`` (CLAUDE_PROJECT_DIR or cwd, except a terminal `.crew` fallback
    cwd re-anchors to its parent with a one-time stderr advisory), IDENTICALLY to
    the review/debate writers, so it targets the anchored project tree. Passing a different ``cwd``
    (while ``project_env`` controls whether CLAUDE_PROJECT_DIR names ``project_dir``)
    is how the anchoring and fallback tests prove swab follows the shared resolver."""
    import argparse as _argparse
    import contextlib as _contextlib
    import io as _io
    from multiagent import cli as _cli

    saved = {k: os.environ.get(k) for k in ("CLAUDE_PROJECT_DIR", "HOME")}
    if project_env:
        os.environ["CLAUDE_PROJECT_DIR"] = str(project_dir)
    else:
        os.environ.pop("CLAUDE_PROJECT_DIR", None)
    os.environ["HOME"] = _NEUTRAL_HOME
    saved_cwd = os.getcwd()
    os.chdir(str(cwd if cwd is not None else project_dir))
    out, err = _io.StringIO(), _io.StringIO()
    try:
        ns = _argparse.Namespace(yes=yes, json=as_json)
        with _contextlib.redirect_stdout(out), _contextlib.redirect_stderr(err):
            rc = _cli.cmd_swab(ns)
    finally:
        os.chdir(saved_cwd)
        for k, v in saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    return rc, out.getvalue(), err.getvalue()


def test_crew_base_phantom_prevention():
    """The bug this whole change closes: run from a SUBDIR of the project with
    CLAUDE_PROJECT_DIR naming the project root, and `.crew` must resolve under the
    PROJECT root, never a phantom `<subdir>/.crew`. Proven non-vacuous by showing
    the pre-fix cwd-relative base would have produced exactly that phantom."""
    log_section("crew_base(): a subdir cwd resolves .crew under the project root")
    from state_discovery import crew_base
    from multiagent import cli as _cli
    from multiagent import review_runs as _rr

    with tempfile.TemporaryDirectory() as td:
        project = Path(td).resolve()
        subdir = project / "sub" / "deeper"
        subdir.mkdir(parents=True)

        saved_cwd = os.getcwd()
        saved_proj = os.environ.get("CLAUDE_PROJECT_DIR")
        os.chdir(str(subdir))
        os.environ["CLAUDE_PROJECT_DIR"] = str(project)
        try:
            base = crew_base()
            reviews = _cli._reviews_subdir("sessP")
            # The pre-fix behavior, resolved against the subdir cwd: a RELATIVE
            # ".crew/reviews" base. This is the phantom the anchor prevents.
            old_relative = _rr.reviews_dir("sessP", base=".crew/reviews")
            phantom = (subdir / old_relative).resolve()
        finally:
            os.chdir(saved_cwd)
            if saved_proj is None:
                os.environ.pop("CLAUDE_PROJECT_DIR", None)
            else:
                os.environ["CLAUDE_PROJECT_DIR"] = saved_proj

        anchored = project / ".crew" / "reviews" / "sessP"
        check("crew_base() resolves to the project root, not the cwd subdir",
              base == project, str(project), str(base))
        check("_reviews_subdir anchors .crew under the project root (no phantom nested .crew)",
              reviews == anchored, str(anchored), str(reviews))
        # Non-vacuity: the phantom is a DISTINCT path under the subdir, and the
        # pre-fix cwd-relative base lands there. The anchored result must NOT.
        check("phantom-prevention is non-vacuous (pre-fix cwd-relative base yields the nested .crew)",
              phantom == (subdir / ".crew" / "reviews" / "sessP").resolve()
              and reviews.resolve() != phantom,
              f"phantom under subdir, distinct from anchored", f"phantom={phantom} reviews={reviews}")


def test_crew_base_spaced_root():
    """A project root path CONTAINING A SPACE. Proves the command recipes' shell
    quoting: crew_base() carries the space intact, `.crew` anchors under the spaced
    root, and a recipe-shaped shell command with the substituted absolute path
    DOUBLE-QUOTED passes it as ONE argument. Non-vacuous: the same command UNQUOTED
    splits on the space and the run fails, so the quotes the recipes add are
    load-bearing, not decorative."""
    log_section("crew_base(): a project root with a SPACE survives recipe shell quoting")
    from state_discovery import crew_base
    from multiagent import cli as _cli

    with tempfile.TemporaryDirectory() as td:
        # A project root whose ABSOLUTE path contains a space: exactly the case an
        # unquoted substitution would word-split.
        project = Path(td) / "pro ject root"
        (project / ".crew").mkdir(parents=True)

        saved_proj = os.environ.get("CLAUDE_PROJECT_DIR")
        os.environ["CLAUDE_PROJECT_DIR"] = str(project)
        try:
            base = crew_base()
            reviews = _cli._reviews_subdir("sessSP")
        finally:
            if saved_proj is None:
                os.environ.pop("CLAUDE_PROJECT_DIR", None)
            else:
                os.environ["CLAUDE_PROJECT_DIR"] = saved_proj

        check("crew_base() preserves the space in the project root (one path, not split)",
              base == project and " " in str(base),
              str(project), str(base))
        anchored = project / ".crew" / "reviews" / "sessSP"
        check("_reviews_subdir anchors .crew under the SPACED project root",
              reviews == anchored, str(anchored), str(reviews))

        # Recipe-shaped shell run: substitute the spaced absolute path into a real
        # `crew render -f <q> -o <out>` command (the debate.md recipe shape) and run
        # it through a REAL shell (shell=True), reproducing exactly the word-splitting
        # the command recipes face. The path args are DOUBLE-QUOTED, as the recipes now
        # mandate.
        cli = MULTIAGENT_DIR / "cli.py"
        qpath = project / "question.md"
        qpath.write_text("Redis or Postgres?\n")
        opath = project / ".crew" / "reviews" / "sessSP" / ".prompt-opus.txt"
        opath.parent.mkdir(parents=True, exist_ok=True)
        py = sys.executable
        env = _neutral_env()
        env["CLAUDE_PROJECT_DIR"] = str(project)

        quoted = (
            f'"{py}" "{cli}" render --mode discuss --seat-role opus '
            f'-f "{qpath}" -o "{opath}"'
        )
        proc_q = subprocess.run(quoted, shell=True, capture_output=True, text=True,
                                env=env, timeout=60)
        check("quoted spaced -f/-o args: recipe shell run succeeds + writes under the spaced .crew",
              proc_q.returncode == 0 and opath.is_file()
              and "Redis or Postgres?" in opath.read_text(),
              "rc=0, prompt written under the spaced .crew",
              f"rc={proc_q.returncode} exists={opath.is_file()} err={proc_q.stderr[:150]}")

        # Non-vacuity: the SAME command with the SAME paths UNQUOTED. The shell splits
        # each path on its space, so `-f` sees a truncated, nonexistent path plus stray
        # args, so the run MUST fail and write nothing, proving the quotes are what make
        # the spaced path work.
        opath.unlink(missing_ok=True)
        unquoted = (
            f'"{py}" "{cli}" render --mode discuss --seat-role opus '
            f'-f {qpath} -o {opath}'
        )
        proc_u = subprocess.run(unquoted, shell=True, capture_output=True, text=True,
                                env=env, timeout=60)
        check("non-vacuity: UNQUOTED spaced args word-split and the run fails (no output file)",
              proc_u.returncode != 0 and not opath.is_file(),
              "rc!=0 and no output file (the space split the arg)",
              f"rc={proc_u.returncode} exists={opath.is_file()}")


def test_crew_base_dot_crew_reanchor():
    """Re-anchor fallback cwd values ending in one or more terminal `.crew` segments."""
    log_section("crew_base(): terminal .crew cwd re-anchors to the project root")
    import contextlib
    import io
    import state_discovery as sd

    with tempfile.TemporaryDirectory() as td:
        root = Path(td).resolve()
        dotcrew = root / ".crew"
        dotcrew.mkdir()
        nested_dotcrew = dotcrew / ".crew"
        # Both terminal directories must exist before their chdir scenarios.
        nested_dotcrew.mkdir()

        saved_cwd = os.getcwd()
        saved_proj = os.environ.get("CLAUDE_PROJECT_DIR")
        try:
            # This reset is guarded because the pre-fix module has no _warned global.
            warned = getattr(sd, "_warned", None)
            if warned is not None:
                warned.clear()
            os.environ.pop("CLAUDE_PROJECT_DIR", None)
            os.chdir(str(dotcrew))
            check("cwd_reanchored detects an unset env plus terminal .crew cwd",
                  sd.cwd_reanchored(), "True", "False")
            err = io.StringIO()
            out = io.StringIO()
            with contextlib.redirect_stderr(err), contextlib.redirect_stdout(out):
                base = sd.crew_base()
                second_base = sd.crew_base()
                anchored = sd.anchor_path(".crew/plans/x.md")
            drift_err = err.getvalue()
            drift_out = out.getvalue()
            pre_fix_base = Path(os.getcwd())
            doubled = (pre_fix_base / ".crew" / "plans" / "x.md").resolve()
            expected_anchor = root / ".crew" / "plans" / "x.md"

            check("unset env plus .crew cwd re-anchors to the project root",
                  base == root and second_base == root,
                  str(root), f"first={base} second={second_base}")
            check("terminal .crew fallback warns exactly once",
                  drift_err.count("ends in .crew") == 1,
                  "one advisory line", repr(drift_err))
            check("terminal .crew advisory names the fallback and re-anchor",
                  ".crew" in drift_err
                  and "CLAUDE_PROJECT_DIR" in drift_err
                  and str(root) in drift_err,
                  "cwd, env name, and project root", repr(drift_err))
            check("terminal .crew advisory stays off stdout",
                  drift_out == "", "empty stdout", repr(drift_out))
            check("terminal .crew anchor_path avoids the doubled .crew",
                  anchored == str(expected_anchor) and anchored != str(doubled),
                  str(expected_anchor), anchored)
            check("terminal .crew regression is non-vacuous before the fix",
                  pre_fix_base == dotcrew
                  and doubled == root / ".crew" / ".crew" / "plans" / "x.md"
                  and anchored != str(doubled),
                  "pre-fix cwd produces a distinct doubled path",
                  f"cwd={pre_fix_base} doubled={doubled} anchored={anchored}")

            os.chdir(str(nested_dotcrew))
            check("cwd_reanchored stays true for a nested terminal .crew cwd",
                  sd.cwd_reanchored(), "True", "False")
            nested_err = io.StringIO()
            nested_out = io.StringIO()
            with contextlib.redirect_stderr(nested_err), contextlib.redirect_stdout(nested_out):
                nested_base = sd.crew_base()
                nested_second_base = sd.crew_base()
                nested_anchor = sd.anchor_path(".crew/plans/x.md")
            nested_warning = nested_err.getvalue()
            nested_pre_fix_base = Path(os.getcwd())
            check("nested terminal .crew cwd strips both segments",
                  nested_base == root
                  and nested_second_base == root
                  and nested_pre_fix_base == nested_dotcrew,
                  str(root),
                  f"first={nested_base} second={nested_second_base} cwd={nested_pre_fix_base}")
            check("nested terminal .crew fallback warns once and stays off stdout",
                  nested_warning.count("ends in .crew") == 1 and nested_out.getvalue() == "",
                  "one stderr advisory and empty stdout", repr(nested_warning))
            check("nested terminal .crew anchor reaches the real .crew tree",
                  nested_anchor == str(expected_anchor), str(expected_anchor), nested_anchor)

            warned = getattr(sd, "_warned", None)
            if warned is not None:
                warned.clear()
            os.environ["CLAUDE_PROJECT_DIR"] = str(root)
            os.chdir(str(dotcrew))
            check("cwd_reanchored is false when CLAUDE_PROJECT_DIR is set",
                  not sd.cwd_reanchored(), "False", "True")
            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                env_base = sd.crew_base()
            check("set env wins over a terminal .crew cwd without warning",
                  env_base == root and err.getvalue() == "",
                  str(root) + " and empty stderr", f"base={env_base} err={err.getvalue()!r}")

            warned = getattr(sd, "_warned", None)
            if warned is not None:
                warned.clear()
            os.environ.pop("CLAUDE_PROJECT_DIR", None)
            os.chdir(str(root))
            check("cwd_reanchored is false for a non-.crew cwd",
                  not sd.cwd_reanchored(), "False", "True")
            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                normal_base = sd.crew_base()
            check("unset env plus normal cwd preserves the current value without warning",
                  normal_base == root and err.getvalue() == "",
                  str(root) + " and empty stderr", f"base={normal_base} err={err.getvalue()!r}")

            warned = getattr(sd, "_warned", None)
            if warned is not None:
                warned.clear()
            os.environ["CLAUDE_PROJECT_DIR"] = ""
            os.chdir(str(root))
            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                empty_normal_base = sd.crew_base()
            check("empty env plus normal cwd follows the unchanged cwd branch",
                  empty_normal_base == root and err.getvalue() == "",
                  str(root) + " and empty stderr",
                  f"base={empty_normal_base} err={err.getvalue()!r}")

            warned = getattr(sd, "_warned", None)
            if warned is not None:
                warned.clear()
            os.chdir(str(dotcrew))
            check("cwd_reanchored treats an empty env as unset",
                  sd.cwd_reanchored(), "True", "False")
            err = io.StringIO()
            with contextlib.redirect_stderr(err):
                empty_dotcrew_base = sd.crew_base()
            check("empty env plus terminal .crew cwd re-anchors like unset env",
                  empty_dotcrew_base == root and err.getvalue().count("ends in .crew") == 1,
                  str(root) + " and one advisory", f"base={empty_dotcrew_base} err={err.getvalue()!r}")
        finally:
            os.chdir(saved_cwd)
            if saved_proj is None:
                os.environ.pop("CLAUDE_PROJECT_DIR", None)
            else:
                os.environ["CLAUDE_PROJECT_DIR"] = saved_proj


def test_swab_reanchor_guard():
    """Refuse destructive pruning from a guessed terminal `.crew` cwd only."""
    log_section("swab: refuse --yes from a re-anchored .crew cwd")

    with tempfile.TemporaryDirectory() as td:
        root = Path(td).resolve()
        orphan = root / ".crew" / "reviews" / "sess-guard" / "run-abcdef123456"
        orphan.mkdir(parents=True)
        (orphan / "run.json").write_text('{"run_id":"run-abcdef123456"}')
        dotcrew = root / ".crew"

        rc, out, err = _swab_run(
            root,
            yes=True,
            as_json=True,
            cwd=dotcrew,
            project_env=False,
        )
        check("swab --yes refuses a guessed artifact root", rc != 0,
              "nonzero", str(rc))
        check("swab refusal deletes nothing", orphan.exists(),
              "orphan present", "orphan deleted")
        check("swab refusal explains re-anchor and recovery",
              "re-anchored off a .crew cwd" in err
              and "artifact root is only a guess" in err
              and "cd to the project root" in err
              and "CLAUDE_PROJECT_DIR" in err,
              "stderr guidance", repr(err))

        rc, out, err = _swab_run(
            root,
            as_json=True,
            cwd=dotcrew,
            project_env=False,
        )
        payload = json.loads(out)
        check("swab dry-run still lists from a re-anchored cwd",
              rc == 0 and [item["name"] for item in payload["prunable"]]
              == ["run-abcdef123456"],
              "run-abcdef123456 listed", str(payload))
        check("swab dry-run does not use the destructive refusal",
              "refusing" not in err.lower(), "no refusal", repr(err))

        rc, out, err = _swab_run(
            root,
            yes=True,
            as_json=True,
            cwd=dotcrew,
        )
        payload = json.loads(out)
        check("swab --yes still deletes with CLAUDE_PROJECT_DIR set",
              rc == 0 and not orphan.exists() and
              [item["name"] for item in payload["removed"]] == ["run-abcdef123456"],
              "run removed", str(payload))


def _old_mtime(path):
    """Age a path past every staleness threshold (8 days)."""
    old = time.time() - 8 * 86400
    os.utime(path, (old, old))


def test_swab():
    log_section("swab: attended artifact pruning")

    with tempfile.TemporaryDirectory() as td:
        td = Path(td)
        _init_repo(td)
        _git(["config", "core.excludesFile", "/dev/null"], td)
        crew = td / ".crew"
        reviews = crew / "reviews" / "sess1"
        reviews.mkdir(parents=True)

        # A real orphaned run: exact mint grammar + run.json, no active loop.
        orphan = reviews / "run-abc123def456"
        orphan.mkdir()
        (orphan / "run.json").write_text('{"run_id":"run-abc123def456"}')
        (orphan / "codex.json").write_text('{"ok":true}')

        # Foreign / malformed names that must NEVER be candidates.
        for bad in ("run-backup", "run-notes2", "run-DEADBEEF", "run-gggggggggggg"):
            d = reviews / bad
            d.mkdir()
            (d / "run.json").write_text("{}")  # even WITH run.json, the name fails
        # A minted-shape name but NO run.json (not crew's, or torn between mkdir/write).
        norj = reviews / "run-000000000000"
        norj.mkdir()

        # A run frozen in an ACTIVE loop is protected at any age.
        live = reviews / "run-1111abcd2222"
        live.mkdir()
        (live / "run.json").write_text('{"run_id":"run-1111abcd2222"}')
        (crew / "build-state-sess1.json").write_text(
            '{"active": true, "run_id": "run-1111abcd2222", "session_id": "sess1"}'
        )

        # A symlinked run dir (name a valid mint) whose target is OUTSIDE reviews/:
        # refused by the resolved-within containment check.
        outside_target = td / "outside-target"
        outside_target.mkdir()
        (outside_target / "run.json").write_text('{"run_id":"run-caf0cafe0caf"}')
        (outside_target / "secret.txt").write_text("do not delete me")
        symrun = reviews / "run-caf0cafe0caf"
        os.symlink(str(outside_target), str(symrun))

        # A symlinked run dir whose target is a real dir INSIDE reviews/ (so the
        # containment check would pass): refused by own_dir's symlink refusal alone,
        # so this proves that guard independently. The target has a non-minted name,
        # so it is never itself a candidate.
        inside_target = reviews / "keepdir"
        inside_target.mkdir()
        (inside_target / "run.json").write_text('{"run_id":"run-dddddddddddd"}')
        (inside_target / "secret.txt").write_text("do not delete me either")
        symrun_in = reviews / "run-dddddddddddd"
        os.symlink(str(inside_target), str(symrun_in))

        # Plans are decisions: never in scope.
        plans = crew / "plans"
        plans.mkdir()
        (plans / "keep.md").write_text("# decision")

        # Debates: stale-no-synthesis pruned; fresh kept; completed kept at any age.
        debates = crew / "debates"
        debates.mkdir()
        stale_deb = debates / "20200101-120000-old"
        stale_deb.mkdir()
        (stale_deb / "question.md").write_text("q")
        _old_mtime(stale_deb)
        fresh_deb = debates / "20990101-120000-new"
        fresh_deb.mkdir()
        (fresh_deb / "question.md").write_text("q")
        done_deb = debates / "20200101-130000-done"
        done_deb.mkdir()
        (done_deb / "synthesis.md").write_text("decided")
        _old_mtime(done_deb)
        user_deb = debates / "my-notes"  # non-generated name
        user_deb.mkdir()
        _old_mtime(user_deb)

        # --- dry-run: lists the two real orphans, deletes NOTHING ---
        rc, out, err = _swab_run(td)
        check("swab dry-run exits 0", rc == 0, "0", str(rc))
        check("swab dry-run names the orphaned review run",
              "run-abc123def456" in out, "run-abc123def456 listed", out)
        check("swab dry-run names the stale debate dir",
              "20200101-120000-old" in out, "stale debate listed", out)
        check("swab dry-run closing line points at --yes",
              "crew swab --yes" in out and "2 items" in out,
              "2 items ... --yes", out)
        check("swab dry-run deletes nothing (orphan survives)", orphan.exists(),
              "orphan present", "gone")
        check("swab dry-run deletes nothing (stale debate survives)",
              stale_deb.exists(), "debate present", "gone")

        # --- dry-run --json shape ---
        rc, out, err = _swab_run(td, as_json=True)
        payload = json.loads(out)
        check("swab --json has prunable/removed/failed/total_bytes",
              set(payload) == {"prunable", "removed", "failed", "total_bytes"},
              "{prunable, removed, failed, total_bytes}", str(sorted(payload)))
        check("swab --json dry-run removed is empty", payload["removed"] == [],
              "[]", str(payload["removed"]))
        check("swab --json dry-run failed is empty", payload["failed"] == [],
              "[]", str(payload["failed"]))
        names = {i["name"] for i in payload["prunable"]}
        check("swab --json prunable = exactly the two orphans",
              names == {"run-abc123def456", "20200101-120000-old"},
              "{run-abc123def456, 20200101-120000-old}", str(names))
        check("swab --json items carry kind/name/path/bytes",
              all(set(i) == {"kind", "name", "path", "bytes"} for i in payload["prunable"]),
              "kind/name/path/bytes", str(payload["prunable"][:1]))
        check("swab --json total_bytes is a positive int",
              isinstance(payload["total_bytes"], int) and payload["total_bytes"] > 0,
              ">0 int", str(payload["total_bytes"]))

        # --- --yes: deletes exactly the prunable set, nothing else ---
        rc, out, err = _swab_run(td, yes=True)
        check("swab --yes exits 0", rc == 0, "0", str(rc))
        check("swab --yes removes the orphaned run", not orphan.exists(),
              "orphan gone", "still present")
        check("swab --yes removes the stale debate", not stale_deb.exists(),
              "debate gone", "still present")
        check("swab --yes reports removed count", "removed 2 items" in out,
              "removed 2 items", out)

        # Everything the guards protect SURVIVES --yes:
        check("foreign run-backup survives --yes", (reviews / "run-backup").exists(),
              "present", "deleted")
        check("foreign run-notes2 survives --yes", (reviews / "run-notes2").exists(),
              "present", "deleted")
        check("wrong-length/case run-DEADBEEF survives --yes",
              (reviews / "run-DEADBEEF").exists(), "present", "deleted")
        check("non-hex run-gggggggggggg survives --yes",
              (reviews / "run-gggggggggggg").exists(), "present", "deleted")
        check("minted-name-but-no-run.json survives --yes", norj.exists(),
              "present", "deleted")
        check("active-loop-owned run survives --yes", live.exists(),
              "present", "deleted")
        check("symlinked run dir (outside target) survives --yes, target intact",
              symrun.exists() and (outside_target / "secret.txt").exists(),
              "link + target present", "followed/deleted")
        check("symlinked run dir (inside target) survives --yes, target intact",
              symrun_in.exists() and (inside_target / "secret.txt").exists(),
              "link + target present", "followed/deleted")
        check("plans dir untouched by --yes", (plans / "keep.md").exists(),
              "plan present", "deleted")
        check("fresh debate survives --yes", fresh_deb.exists(),
              "present", "deleted")
        check("completed debate (synthesis.md) survives --yes", done_deb.exists(),
              "present", "deleted")
        check("user-named debate dir survives --yes", user_deb.exists(),
              "present", "deleted")

        # --- clean tree: nothing left to swab ---
        rc, out, err = _swab_run(td)
        check("swab on a clean tree reports decks clean",
              "decks are clean" in out, "decks are clean", out)

    # --- flat/sessionless layout: run dir directly under reviews/ ---
    with tempfile.TemporaryDirectory() as td:
        td = Path(td)
        flat = Path(td) / ".crew" / "reviews" / "run-0a1b2c3d4e5f"
        flat.mkdir(parents=True)
        (flat / "run.json").write_text('{"run_id":"run-0a1b2c3d4e5f"}')
        rc, out, err = _swab_run(td, as_json=True)
        payload = json.loads(out)
        check("swab lists a flat sessionless orphan run",
              [i["name"] for i in payload["prunable"]] == ["run-0a1b2c3d4e5f"],
              "run-0a1b2c3d4e5f", str(payload["prunable"]))
        rc, out, err = _swab_run(td, yes=True)
        check("swab --yes removes a flat sessionless orphan run", not flat.exists(),
              "gone", "present")

    # --- pointer hygiene helper: drop_dangling_pointer removes a pointer left
    # naming a just-removed run. Through swab a POINTED run is now protected (see
    # the in-flight cases above), so this belt-and-suspenders helper is exercised
    # directly: it drops the pointer iff its run_id is in the removed set, and
    # leaves a pointer naming a surviving run untouched. ---
    from multiagent import review_runs as _rr
    import artifact_prune as _ap
    with tempfile.TemporaryDirectory() as td:
        sess = Path(td) / ".crew" / "reviews" / "sessP"
        sess.mkdir(parents=True)
        (sess / _rr.POINTER_NAME).write_text('{"run_id":"run-deadbeef0000"}')
        _ap.drop_dangling_pointer(sess, {"run-deadbeef0000"})
        check("drop_dangling_pointer drops a pointer naming a removed run",
              not (sess / _rr.POINTER_NAME).exists(), "pointer gone", "dangling")
        # A pointer naming a DIFFERENT (surviving) run is left alone.
        (sess / _rr.POINTER_NAME).write_text('{"run_id":"run-cafecafe0000"}')
        _ap.drop_dangling_pointer(sess, {"run-deadbeef0000"})
        check("drop_dangling_pointer keeps a pointer naming a surviving run",
              (sess / _rr.POINTER_NAME).exists(), "pointer kept", "dropped")

    # --- in-flight protection: a run named by a current-run.json survives --yes ---
    # (a standalone review, or a loop run prepped before begin-review froze it, is
    # named by NO loop yet, so only the pointer protects it from a mid-review --yes.)
    with tempfile.TemporaryDirectory() as td:
        td = Path(td)
        reviews = Path(td) / ".crew" / "reviews" / "sessX"
        reviews.mkdir(parents=True)
        # In play: pointed at by the SESSION pointer, no loop names it.
        inflight = reviews / "run-aaaabbbbcccc"
        inflight.mkdir()
        (inflight / "run.json").write_text('{"run_id":"run-aaaabbbbcccc"}')
        (reviews / "current-run.json").write_text('{"run_id":"run-aaaabbbbcccc"}')
        # A genuine orphan in the SAME session: no loop, no pointer names it.
        orph = reviews / "run-ddddeeeeffff"
        orph.mkdir()
        (orph / "run.json").write_text('{"run_id":"run-ddddeeeeffff"}')

        rc, out, err = _swab_run(td, as_json=True)
        names = {i["name"] for i in json.loads(out)["prunable"]}
        check("session pointer-named run is NOT prunable",
              "run-aaaabbbbcccc" not in names, "protected", str(names))
        check("orphan alongside a pointer IS still prunable",
              "run-ddddeeeeffff" in names, "prunable", str(names))
        rc, out, err = _swab_run(td, yes=True)
        check("session pointer-named run survives --yes", inflight.exists(),
              "present", "deleted")
        check("orphan alongside a pointer is removed by --yes", not orph.exists(),
              "gone", "present")

    # --- flat current-run.json protects a flat sessionless run ---
    with tempfile.TemporaryDirectory() as td:
        td = Path(td)
        flat_reviews = Path(td) / ".crew" / "reviews"
        flat_reviews.mkdir(parents=True)
        pointed = flat_reviews / "run-1a2b3c4d5e6f"
        pointed.mkdir()
        (pointed / "run.json").write_text('{"run_id":"run-1a2b3c4d5e6f"}')
        (flat_reviews / "current-run.json").write_text('{"run_id":"run-1a2b3c4d5e6f"}')
        rc, out, err = _swab_run(td, as_json=True)
        names = {i["name"] for i in json.loads(out)["prunable"]}
        check("flat pointer-named run is NOT prunable",
              "run-1a2b3c4d5e6f" not in names, "protected", str(names))
        _swab_run(td, yes=True)
        check("flat pointer-named run survives --yes", pointed.exists(),
              "present", "deleted")

    # --- root resolution: swab anchors to CLAUDE_PROJECT_DIR (crew_base), not cwd ---
    # Every .crew path derives from the ONE crew_base() resolver now, so a
    # destructive command targets the SAME anchored .crew the review/debate writers
    # resolve, even when cwd diverges from CLAUDE_PROJECT_DIR.
    with tempfile.TemporaryDirectory() as project_tree, \
         tempfile.TemporaryDirectory() as other_cwd:
        project_tree = Path(project_tree)
        pr = project_tree / ".crew" / "reviews" / "sessW"
        pr.mkdir(parents=True)
        prun = pr / "run-9f8e7d6c5b4a"
        prun.mkdir()
        (prun / "run.json").write_text('{"run_id":"run-9f8e7d6c5b4a"}')
        # CLAUDE_PROJECT_DIR = the project tree; cwd points ELSEWHERE (empty). If
        # swab still followed cwd it would enumerate the empty other_cwd and find
        # nothing, so this assertion is non-vacuous: it fails unless swab anchors.
        rc, out, err = _swab_run(project_tree, as_json=True, cwd=other_cwd)
        names = {i["name"] for i in json.loads(out)["prunable"]}
        check("swab enumerates the CLAUDE_PROJECT_DIR tree (ignores divergent cwd)",
              names == {"run-9f8e7d6c5b4a"},
              "run-9f8e7d6c5b4a", str(names))

    # --- --yes exits nonzero on a failed delete; --json lists it under failed ---
    with tempfile.TemporaryDirectory() as td:
        td = Path(td)
        reviews_root = Path(td) / ".crew" / "reviews"
        good_sess = reviews_root / "sessG"
        good_sess.mkdir(parents=True)
        good = good_sess / "run-000000000000"
        good.mkdir()
        (good / "run.json").write_text('{"run_id":"run-000000000000"}')
        # An undeletable orphan: rmdir of the run dir needs write on its parent
        # session dir, so a read+exec-only parent makes the final rmdir fail.
        bad_sess = reviews_root / "sessB"
        bad_sess.mkdir()
        bad = bad_sess / "run-111111111111"
        bad.mkdir()
        (bad / "run.json").write_text('{"run_id":"run-111111111111"}')
        os.chmod(bad_sess, 0o500)
        try:
            rc, out, err = _swab_run(td, yes=True, as_json=True)
            payload = json.loads(out)
            check("swab --yes exits nonzero when a delete failed", rc == 1,
                  "1", str(rc))
            failed_names = {i["name"] for i in payload["failed"]}
            check("swab --yes lists the undeletable run under failed",
                  "run-111111111111" in failed_names, "failed lists it",
                  str(failed_names))
            removed_names = {i["name"] for i in payload["removed"]}
            check("swab --yes still removes the deletable run",
                  "run-000000000000" in removed_names and not good.exists(),
                  "good removed", str(removed_names))
        finally:
            os.chmod(bad_sess, 0o755)

    # --- nested candidate dedupe: a minted run planted inside a flat run is listed
    # ONCE (the outermost), so bytes aren't double-counted and --yes never rmtree's
    # a parent then hits the vanished child as a false failure. ---
    with tempfile.TemporaryDirectory() as td:
        td = Path(td)
        reviews_root = Path(td) / ".crew" / "reviews"
        outer = reviews_root / "run-aaaaaaaaaaaa"
        outer.mkdir(parents=True)
        (outer / "run.json").write_text('{"run_id":"run-aaaaaaaaaaaa"}')
        inner = outer / "run-bbbbbbbbbbbb"
        inner.mkdir()
        (inner / "run.json").write_text('{"run_id":"run-bbbbbbbbbbbb"}')

        rc, out, err = _swab_run(td, as_json=True)
        names = [i["name"] for i in json.loads(out)["prunable"]]
        check("nested run inside a flat run is listed once (outermost only)",
              names == ["run-aaaaaaaaaaaa"], "[run-aaaaaaaaaaaa]", str(names))
        rc, out, err = _swab_run(td, yes=True, as_json=True)
        payload = json.loads(out)
        check("swab --yes removes the nested subtree with no false failure",
              rc == 0 and payload["failed"] == [] and not outer.exists(),
              "clean removal", f"rc={rc} failed={payload['failed']}")

    # --- symlinked `.crew` ROOT: a `.crew` that is a symlink out of the tree means
    # this is not the tree crew created. own_dir refuses a symlinked reviews_root
    # BELOW, but a symlinked `.crew` PARENT one level up leaves a real .crew/reviews
    # at the link target, so without the own_dir(crew_dir) guard a --yes would
    # rmtree dirs outside the project. collect_prunable must return [] and swab must
    # prune NOTHING. ---
    with tempfile.TemporaryDirectory() as td:
        td = Path(td)
        # A real crew tree with a genuine orphan run, OUTSIDE the project.
        real_tree = td / "real"
        real_reviews = real_tree / ".crew" / "reviews" / "sessS"
        real_reviews.mkdir(parents=True)
        real_run = real_reviews / "run-abcabc123123"
        real_run.mkdir()
        (real_run / "run.json").write_text('{"run_id":"run-abcabc123123"}')
        # The project's `.crew` is a SYMLINK to that out-of-tree crew dir.
        project = td / "proj"
        project.mkdir()
        os.symlink(str(real_tree / ".crew"), str(project / ".crew"))

        import artifact_prune as _ap_sym
        # crew_dir cwd-relative == Path(".crew") when run in the project.
        saved_cwd = os.getcwd()
        os.chdir(str(project))
        try:
            direct = _ap_sym.collect_prunable(Path(".crew"), time.time())
        finally:
            os.chdir(saved_cwd)
        check("collect_prunable returns [] under a symlinked .crew root",
              direct == [], "[]", str([p.name for p in direct]))

        rc, out, err = _swab_run(project, as_json=True)
        names = {i["name"] for i in json.loads(out)["prunable"]}
        check("swab lists nothing under a symlinked .crew root",
              names == set(), "empty", str(names))
        rc, out, err = _swab_run(project, yes=True)
        check("swab --yes prunes nothing through a symlinked .crew root "
              "(out-of-tree run intact)", real_run.exists(),
              "run intact", "followed/deleted")


if __name__ == "__main__":
    main()
